-- Paraf schema for MySQL 8 (InnoDB). Generated by `pnpm --filter @paraf/mysql schema`;
-- do not edit by hand. Equivalent to `MySqlStore#migrate()` with the default prefix.
-- IDs are BINARY(16) UUIDs and times are DATETIME(3) in UTC.

CREATE TABLE IF NOT EXISTS paraf_migrations (
  version     INT          NOT NULL PRIMARY KEY,
  name        VARCHAR(100) NOT NULL,
  applied_at  DATETIME(3)  NOT NULL DEFAULT (UTC_TIMESTAMP(3))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;

-- 1: initial schema
CREATE TABLE IF NOT EXISTS paraf_flows (
  flow_id      VARCHAR(100) NOT NULL,
  version      INT          NOT NULL,
  name         VARCHAR(255) NOT NULL,
  definition   JSON         NOT NULL,
  created_by   VARCHAR(255),
  created_at   DATETIME(3)  NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
  PRIMARY KEY (flow_id, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS paraf_flow_heads (
  flow_id         VARCHAR(100) NOT NULL PRIMARY KEY,
  active_version  INT          NOT NULL,
  updated_at      DATETIME(3)  NOT NULL DEFAULT (UTC_TIMESTAMP(3)),
  FOREIGN KEY (flow_id, active_version) REFERENCES paraf_flows (flow_id, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS paraf_instances (
  id                  BINARY(16)   NOT NULL PRIMARY KEY,
  flow_id             VARCHAR(100) NOT NULL,
  flow_version        INT          NOT NULL,
  subject_type        VARCHAR(100) NOT NULL,
  subject_id          VARCHAR(255) NOT NULL,
  requester_id        VARCHAR(255) NOT NULL,
  status              VARCHAR(20)  NOT NULL,
  current_step_id     BINARY(16),
  round               INT          NOT NULL DEFAULT 1,
  document            JSON         NOT NULL,
  revision            INT          NOT NULL DEFAULT 0,
  created_at          DATETIME(3)  NOT NULL,
  updated_at          DATETIME(3)  NOT NULL,
  completed_at        DATETIME(3),
  active_subject_key  VARCHAR(360),
  UNIQUE KEY uq_paraf_inst_active_subject (active_subject_key),
  KEY idx_paraf_inst_subject (subject_type, subject_id),
  KEY idx_paraf_inst_status (status),
  FOREIGN KEY (flow_id, flow_version) REFERENCES paraf_flows (flow_id, version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS paraf_steps (
  id            BINARY(16)   NOT NULL PRIMARY KEY,
  instance_id   BINARY(16)   NOT NULL,
  position      INT          NOT NULL,
  node_id       VARCHAR(100) NOT NULL,
  iteration     INT          NOT NULL,
  chain_level   INT          NOT NULL DEFAULT 0,
  round         INT          NOT NULL,
  status        VARCHAR(20)  NOT NULL,
  config        JSON         NOT NULL,
  entered_at    DATETIME(3)  NOT NULL,
  due_at        DATETIME(3),
  completed_at  DATETIME(3),
  UNIQUE KEY (instance_id, node_id, iteration, chain_level),
  KEY idx_paraf_steps_due (status, due_at),
  FOREIGN KEY (instance_id) REFERENCES paraf_instances (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS paraf_approvers (
  id              BINARY(16)   NOT NULL PRIMARY KEY,
  step_id         BINARY(16)   NOT NULL,
  instance_id     BINARY(16)   NOT NULL,
  position        INT          NOT NULL,
  group_id        VARCHAR(100) NOT NULL DEFAULT 'default',
  user_id         VARCHAR(255) NOT NULL,
  source          JSON,
  status          VARCHAR(20)  NOT NULL,
  delegated_from  VARCHAR(255),
  auto_from_step  BINARY(16),
  decided_at      DATETIME(3),
  comment         TEXT,
  UNIQUE KEY (step_id, group_id, user_id),
  KEY idx_paraf_appr_user_pending (user_id, status),
  KEY idx_paraf_appr_instance (instance_id),
  FOREIGN KEY (step_id) REFERENCES paraf_steps (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE IF NOT EXISTS paraf_audit (
  seq          BIGINT       NOT NULL AUTO_INCREMENT,
  id           BINARY(16)   NOT NULL PRIMARY KEY,
  instance_id  BINARY(16)   NOT NULL,
  step_id      BINARY(16),
  node_id      VARCHAR(100),
  action       VARCHAR(50)  NOT NULL,
  actor_id     VARCHAR(255),
  comment      TEXT,
  metadata     JSON,
  created_at   DATETIME(3)  NOT NULL,
  UNIQUE KEY (seq),
  KEY idx_paraf_audit_instance (instance_id, seq),
  FOREIGN KEY (instance_id) REFERENCES paraf_instances (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT IGNORE INTO paraf_migrations (version, name) VALUES (1, 'initial schema');
